1	//! Pipeline-level transform stages. A [`TransformStage`] wraps one of six
2	//! shapes:
3	//!
4	//! - [`TransformStage::Map`] holds an unchanged 1→1 [`RecordTransform`].
5	//! - [`TransformStage::Filter`] is a predicate-based 1→0|1 stage.
6	//! - [`TransformStage::Explode`] expands an array field into 1→0..N output
7	//!   records.
8	//! - [`TransformStage::CdcUnwrap`] normalizes a CDC change-event envelope
9	//!   (`{op, before, after, …}`) into a flat row plus a marker field; DDL and
10	//!   truncate events are dropped (1→0|1).
11	//! - [`TransformStage::Custom`] is an `Fn(Value) -> Vec<Value>` closure
12	//!   escape hatch for library callers.
13	//! - [`TransformStage::PageFn`] is a `Fn(Vec<Value>) -> Result<Vec<Value>,
14	//!   FaucetError>` whole-batch closure for transforms that need the full page
15	//!   at once (SQL, sort, dedup, top-N). Not addressable from YAML.
16	//!
17	//! [`apply_stages_to_page`] is the page-granular runner: per-record stages
18	//! (`Map`/`Filter`/`Explode`/`Custom`) flat-map over each record in order,
19	//! while `PageFn` stages receive and return the whole page slice. Declared
20	//! order is preserved, so `filter → sql → select` works as expected.
21	//! The observability wrapper [`crate::observability::instrumented_apply_stages`]
22	//! wraps `apply_stages_to_page` and aggregates per-page metrics.
23	
24	use crate::error::FaucetError;
25	use crate::transform::{CompiledTransform, RecordTransform, compile as compile_record};
26	use serde_json::Value;
27	use std::sync::Arc;
28	
29	/// Type alias for the page-level transform closure stored in
30	/// [`TransformStage::PageFn`] and [`CompiledStage::PageFn`].
31	pub type PageFnBox = Arc<dyn Fn(Vec<Value>) -> Result<Vec<Value>, FaucetError> + Send + Sync>;
32	
33	/// One stage in a transform pipeline.
34	pub enum TransformStage {
35	    /// Existing 1→1 record transform. Wraps unchanged.
36	    Map(RecordTransform),
37	    /// Predicate-based 1→0|1 stage. Keeps the record iff the predicate
38	    /// evaluates true.
39	    #[cfg(feature = "transform-filter")]
40	    Filter(FilterSpec),
41	    /// Array-expansion 1→0..N stage. Fans the record out once per element
42	    /// of the targeted array; object elements are merged into the parent
43	    /// container with a prefix, scalars/arrays replace the leaf in place.
44	    #[cfg(feature = "transform-explode")]
45	    Explode(ExplodeSpec),
46	    /// CDC envelope → flat row + marker. 1→0|1.
47	    /// Normalizes `{op, before, after, …}` into a flat row stamped with
48	    /// `__op: "u"` (upsert) or `__op: "d"` (delete). DDL/truncate events
49	    /// are dropped entirely.
50	    #[cfg(feature = "transform-cdc-unwrap")]
51	    CdcUnwrap(CdcUnwrapSpec),
52	    /// Arbitrary 0..N closure for library callers (not addressable from YAML).
53	    Custom(Arc<dyn Fn(Value) -> Vec<Value> + Send + Sync>),
54	    /// Page-level closure: sees the whole page, returns a new page; fallible.
55	    /// The escape hatch for transforms that need the full batch at once (SQL,
56	    /// sort, dedup, top-N). Dependency-free; built by connectors/CLI, not
57	    /// addressable as a per-record stage.
58	    PageFn(PageFnBox),
59	}
60	
61	impl std::fmt::Debug for TransformStage {
62	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
63	        match self {
64	            Self::Map(t) => f.debug_tuple("Map").field(t).finish(),
65	            #[cfg(feature = "transform-filter")]
66	            Self::Filter(s) => f.debug_tuple("Filter").field(s).finish(),
67	            #[cfg(feature = "transform-explode")]
68	            Self::Explode(s) => f.debug_tuple("Explode").field(s).finish(),
69	            #[cfg(feature = "transform-cdc-unwrap")]
70	            Self::CdcUnwrap(s) => f.debug_tuple("CdcUnwrap").field(s).finish(),
71	            Self::Custom(_) => write!(f, "Custom(<fn>)"),
72	            Self::PageFn(_) => write!(f, "PageFn(<fn>)"),
73	        }
74	    }
75	}
