77	impl Clone for TransformStage {
78	    fn clone(&self) -> Self {
79	        match self {
80	            Self::Map(t) => Self::Map(t.clone()),
81	            #[cfg(feature = "transform-filter")]
82	            Self::Filter(s) => Self::Filter(s.clone()),
83	            #[cfg(feature = "transform-explode")]
84	            Self::Explode(s) => Self::Explode(s.clone()),
85	            #[cfg(feature = "transform-cdc-unwrap")]
86	            Self::CdcUnwrap(s) => Self::CdcUnwrap(s.clone()),
87	            Self::Custom(f) => Self::Custom(Arc::clone(f)),
88	            Self::PageFn(f) => Self::PageFn(Arc::clone(f)),
89	        }
90	    }
91	}
