93	/// Pre-compiled stage. Per-record work is just lookup + comparison + flat-map.
94	pub enum CompiledStage {
95	    Map(CompiledTransform),
96	    #[cfg(feature = "transform-filter")]
97	    Filter(CompiledFilter),
98	    #[cfg(feature = "transform-explode")]
99	    Explode(CompiledExplode),
100	    #[cfg(feature = "transform-cdc-unwrap")]
101	    CdcUnwrap(CompiledCdcUnwrap),
102	    Custom(Arc<dyn Fn(Value) -> Vec<Value> + Send + Sync>),
103	    PageFn(PageFnBox),
104	}
