106	impl std::fmt::Debug for CompiledStage {
107	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
108	        match self {
109	            Self::Map(_) => write!(f, "Map(<compiled>)"),
110	            #[cfg(feature = "transform-filter")]
111	            Self::Filter(cf) => f.debug_tuple("Filter").field(cf).finish(),
112	            #[cfg(feature = "transform-explode")]
113	            Self::Explode(e) => f.debug_tuple("Explode").field(e).finish(),
114	            #[cfg(feature = "transform-cdc-unwrap")]
115	            Self::CdcUnwrap(c) => f.debug_tuple("CdcUnwrap").field(c).finish(),
116	            Self::Custom(_) => write!(f, "Custom(<fn>)"),
117	            Self::PageFn(_) => write!(f, "PageFn(<fn>)"),
118	        }
119	    }
120	}
