122	impl Clone for CompiledStage {
123	    fn clone(&self) -> Self {
124	        match self {
125	            Self::Map(t) => Self::Map(t.clone()),
126	            #[cfg(feature = "transform-filter")]
127	            Self::Filter(f) => Self::Filter(CompiledFilter {
128	                path: f.path.clone(),
129	                op: f.op,
130	                value: f.value.clone(),
131	            }),
132	            #[cfg(feature = "transform-explode")]
133	            Self::Explode(e) => Self::Explode(CompiledExplode {
134	                path: e.path.clone(),
135	                prefix: e.prefix.clone(),
136	                separator: e.separator.clone(),
137	                on_missing: e.on_missing,
138	            }),
139	            #[cfg(feature = "transform-cdc-unwrap")]
140	            Self::CdcUnwrap(c) => Self::CdcUnwrap(c.clone()),
141	            Self::Custom(f) => Self::Custom(Arc::clone(f)),
142	            Self::PageFn(f) => Self::PageFn(Arc::clone(f)),
143	        }
144	    }
145	}
