147	// ── JSONPath subset: bare key | $.dot.path | $['bracketed key'] ─────────────
148	
149	#[derive(Debug, Clone, PartialEq, Eq)]
150	pub enum PathSegment {
151	    /// `.key` or `['key']` — addresses a JSON object field by name.
152	    Key(String),
153	}
154	
155	/// Pre-parsed JSONPath. Bad syntax surfaces at `compile_stage` time, not per
156	/// record. The implementation is a hand-rolled parser for the v1 subset
157	/// (bare key, dot path, bracketed string key) — sufficient because we need
158	/// to walk parent-container chains for explode mutation, which the
159	/// `jsonpath_rust::query()` API doesn't expose.
160	#[derive(Debug, Clone, PartialEq, Eq)]
161	pub struct CompiledPath {
162	    /// Normalised string form (always `$`-rooted) for error messages.
163	    pub normalised: String,
164	    /// Parsed segments. Empty = the record itself.
165	    segments: Vec<PathSegment>,
166	}
167	
168	impl CompiledPath {
169	    /// Parse a v1-subset path. Rejects wildcards (`[*]`), recursive descent
170	    /// (`..`), and filter expressions (`[?(...)]`) at compile time.
171	    pub fn compile(raw: &str) -> Result<Self, FaucetError> {
172	        let normalised = if raw.starts_with('$') {
173	            raw.to_owned()
174	        } else {
175	            format!("$.{raw}")
176	        };
177	        // Helper: the canonical "v1 doesn't support this syntax" error.
178	        // Wildcards (`[*]`), recursive descent (`..`), and filters (`[?...]`)
179	        // are rejected at the *syntax* level — but those substrings can
180	        // legitimately appear *inside* a quoted bracket key (e.g.
181	        // `$['a..b']`, `$['x[*]y']`), which is the documented escape hatch
182	        // for unusual keys. So we only reject them when they appear as
183	        // structural syntax during tokenisation, not as content.
184	        let v1_syntax_err = || {
185	            FaucetError::Transform(format!(
186	                "invalid path '{raw}': only single-node paths are supported \
187	                 ('[*]', '..', '[?]' not allowed in this layer)"
188	            ))
189	        };
190	        let mut segments: Vec<PathSegment> = Vec::new();
191	        // Strip the leading `$`. The remainder is a series of `.<ident>` or
192	        // `['key']` chunks.
193	        let mut rest = &normalised[1..];
194	        while !rest.is_empty() {
195	            if let Some(after_dot) = rest.strip_prefix('.') {
196	                // Recursive descent `..` shows up here as an empty identifier
197	                // (the next char is another `.`). Reject with the v1 message.
198	                if after_dot.starts_with('.') {
199	                    return Err(v1_syntax_err());
200	                }
201	                // Read an identifier up to the next `.` or `[`.
202	                let end = after_dot.find(['.', '[']).unwrap_or(after_dot.len());
203	                let key = &after_dot[..end];
204	                if key.is_empty() {
205	                    return Err(FaucetError::Transform(format!(
206	                        "invalid path '{raw}': empty segment after '.'"
207	                    )));
208	                }
209	                segments.push(PathSegment::Key(key.to_owned()));
210	                rest = &after_dot[end..];
211	            } else if let Some(after_open) = rest.strip_prefix('[') {
212	                // Expect ['key'] or ["key"]. A wildcard (`[*]`) or filter
213	                // (`[?...]`) shows up here as an unquoted next-char — catch
214	                // those with the v1 message before the generic "needs a
215	                // quoted key" error.
216	                let next = after_open.chars().next().ok_or_else(|| {
217	                    FaucetError::Transform(format!("invalid path '{raw}': unterminated bracket"))
218	                })?;
219	                if next == '*' || next == '?' {
220	                    return Err(v1_syntax_err());
221	                }
222	                if next != '\'' && next != '"' {
223	                    return Err(FaucetError::Transform(format!(
224	                        "invalid path '{raw}': bracket form requires a quoted key"
225	                    )));
226	                }
227	                let quote = next;
228	                let after_quote = &after_open[quote.len_utf8()..];
229	                let close = after_quote.find(quote).ok_or_else(|| {
230	                    FaucetError::Transform(format!("invalid path '{raw}': unterminated quoted key"))
231	                })?;
232	                let key = &after_quote[..close];
233	                let after_close_quote = &after_quote[close + quote.len_utf8()..];
234	                let after_close_bracket = after_close_quote.strip_prefix(']').ok_or_else(|| {
235	                    FaucetError::Transform(format!(
236	                        "invalid path '{raw}': expected ']' after quoted key"
237	                    ))
238	                })?;
239	                segments.push(PathSegment::Key(key.to_owned()));
240	                rest = after_close_bracket;
241	            } else {
242	                return Err(FaucetError::Transform(format!(
243	                    "invalid path '{raw}': unexpected character at '{rest}'"
244	                )));
245	            }
246	        }
247	        if segments.is_empty() {
248	            return Err(FaucetError::Transform(format!(
249	                "invalid path '{raw}': empty (must address a key)"
250	            )));
251	        }
252	        Ok(Self {
253	            normalised,
254	            segments,
255	        })
256	    }
257	
258	    /// All segments of the path.
259	    pub fn segments(&self) -> &[PathSegment] {
260	        &self.segments
261	    }
262	
263	    /// Last segment's key (used for explode's default prefix).
264	    pub fn last_segment(&self) -> &str {
265	        match self.segments.last() {
266	            Some(PathSegment::Key(k)) => k,
267	            None => "",
268	        }
269	    }
270	
271	    /// Return `(parent_segments, leaf_key)` for mutation. Top-level paths
272	    /// return `(&[], leaf)` — the parent is the record itself.
273	    pub fn parent_and_leaf(&self) -> (&[PathSegment], &str) {
274	        let n = self.segments.len();
275	        let parent = &self.segments[..n - 1];
276	        let leaf = match &self.segments[n - 1] {
277	            PathSegment::Key(k) => k.as_str(),
278	        };
279	        (parent, leaf)
280	    }
281	
282	    /// Resolve the path against a value. Returns `Ok(None)` for missing
283	    /// (key absent or walking through a non-object); `Ok(Some(&v))` if found.
284	    pub fn resolve<'a>(&self, value: &'a Value) -> Result<Option<&'a Value>, FaucetError> {
285	        Self::resolve_segments(value, &self.segments)
286	    }
287	
288	    /// Resolve an explicit slice of segments — used to walk the parent
289	    /// container chain returned by `parent_and_leaf`.
290	    pub fn resolve_segments<'a>(
291	        value: &'a Value,
292	        segments: &[PathSegment],
293	    ) -> Result<Option<&'a Value>, FaucetError> {
294	        let mut cur = value;
295	        for seg in segments {
296	            let PathSegment::Key(k) = seg;
297	            match cur {
298	                Value::Object(map) => match map.get(k) {
299	                    Some(v) => cur = v,
300	                    None => return Ok(None),
301	                },
302	                _ => return Ok(None),
303	            }
304	        }
305	        Ok(Some(cur))
306	    }
307	
308	    /// Resolve a path that must end at an `Object` container, returning a
309	    /// mutable reference. Used by explode to mutate the parent container.
310	    /// Returns `Ok(None)` if any intermediate is missing or non-object.
311	    pub fn resolve_segments_mut<'a>(
312	        value: &'a mut Value,
313	        segments: &[PathSegment],
314	    ) -> Result<Option<&'a mut serde_json::Map<String, Value>>, FaucetError> {
315	        let mut cur = value;
316	        for seg in segments {
317	            let PathSegment::Key(k) = seg;
318	            match cur {
319	                Value::Object(map) => match map.get_mut(k) {
320	                    Some(v) => cur = v,
321	                    None => return Ok(None),
322	                },
323	                _ => return Ok(None),
324	            }
325	        }
326	        match cur {
327	            Value::Object(map) => Ok(Some(map)),
328	            _ => Ok(None),
329	        }
330	    }
331	}
