333	// ── Filter spec ──
334	
335	/// Predicate spec for [`TransformStage::Filter`]. Compiled into a
336	/// [`CompiledFilter`] at pipeline-build time; per-record work is a single
337	/// path resolve + comparison.
338	#[cfg(feature = "transform-filter")]
339	#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, schemars::JsonSchema)]
340	pub struct FilterSpec {
341	    /// JSONPath subset (bare key, dot path, bracketed string key).
342	    pub path: String,
343	    /// Comparison operator.
344	    pub op: FilterOp,
345	    /// Required for `eq`, `ne`, `in`, `not_in`. Forbidden for `exists`.
346	    /// For `in` / `not_in`, must be a JSON array.
347	    #[serde(default, skip_serializing_if = "Option::is_none")]
348	    pub value: Option<Value>,
349	}
350	
351	/// Comparison operator for [`FilterSpec`].
352	#[cfg(feature = "transform-filter")]
353	#[derive(
354	    Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize, schemars::JsonSchema,
355	)]
356	#[serde(rename_all = "snake_case")]
357	pub enum FilterOp {
358	    /// `path == value` (JSON equality; missing path → false).
359	    Eq,
360	    /// `path != value` (JSON inequality; missing path → true).
361	    Ne,
362	    /// `path` is present and non-null.
363	    Exists,
364	    /// `path`'s value is a member of `value` (must be an array).
365	    /// Missing path → false.
366	    In,
367	    /// `path`'s value is NOT a member of `value` (must be an array).
368	    /// Missing path → true.
369	    NotIn,
370	}
371	
372	#[cfg(feature = "transform-filter")]
373	impl std::fmt::Display for FilterOp {
374	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
375	        f.write_str(match self {
376	            FilterOp::Eq => "eq",
377	            FilterOp::Ne => "ne",
378	            FilterOp::Exists => "exists",
379	            FilterOp::In => "in",
380	            FilterOp::NotIn => "not_in",
381	        })
382	    }
383	}
