385	/// Pre-compiled filter: path parsed once, value cloned once.
386	///
387	/// `pub` (rather than the spec's `pub(crate)`) so it can sit inside the
388	/// `pub` [`CompiledStage::Filter`] variant without tripping the
389	/// `private_interfaces` lint — same shape as the already-`pub`
390	/// [`CompiledTransform`] sibling that backs [`CompiledStage::Map`].
391	#[cfg(feature = "transform-filter")]
392	#[derive(Debug)]
393	pub struct CompiledFilter {
394	    pub path: CompiledPath,
395	    pub op: FilterOp,
396	    pub value: Option<Value>,
397	}
398	
399	#[cfg(feature = "transform-filter")]
400	impl CompiledFilter {
401	    fn compile(spec: &FilterSpec) -> Result<Self, FaucetError> {
402	        // Validate op/value combo at compile time so bad configs fail fast.
403	        match spec.op {
404	            FilterOp::Exists => {
405	                if spec.value.is_some() {
406	                    return Err(FaucetError::Transform(
407	                        "filter: op 'exists' must not have a `value`".to_owned(),
408	                    ));
409	                }
410	            }
411	            FilterOp::Eq | FilterOp::Ne => {
412	                if spec.value.is_none() {
413	                    return Err(FaucetError::Transform(format!(
414	                        "filter: op '{}' requires a `value`",
415	                        spec.op
416	                    )));
417	                }
418	            }
419	            FilterOp::In | FilterOp::NotIn => {
420	                if !matches!(spec.value, Some(Value::Array(_))) {
421	                    return Err(FaucetError::Transform(format!(
422	                        "filter: op '{}' requires an array `value`",
423	                        spec.op
424	                    )));
425	                }
426	            }
427	        }
428	        let path = CompiledPath::compile(&spec.path).map_err(|e| match e {
429	            FaucetError::Transform(msg) => FaucetError::Transform(format!("filter: {msg}")),
430	            other => other,
431	        })?;
432	        Ok(Self {
433	            path,
434	            op: spec.op,
435	            value: spec.value.clone(),
436	        })
437	    }
438	
439	    fn evaluate(&self, rec: &Value) -> Result<bool, FaucetError> {
440	        let resolved = self.path.resolve(rec)?;
441	        Ok(match self.op {
442	            FilterOp::Eq => resolved
443	                .map(|v| v == self.value.as_ref().unwrap())
444	                .unwrap_or(false),
445	            FilterOp::Ne => resolved
446	                .map(|v| v != self.value.as_ref().unwrap())
447	                .unwrap_or(true), // missing → keep
448	            FilterOp::Exists => matches!(resolved, Some(v) if !v.is_null()),
449	            FilterOp::In => match resolved {
450	                Some(v) => {
451	                    let arr = self
452	                        .value
453	                        .as_ref()
454	                        .unwrap()
455	                        .as_array()
456	                        .expect("compile validated");
457	                    arr.contains(v)
458	                }
459	                None => false,
460	            },
461	            FilterOp::NotIn => match resolved {
462	                Some(v) => {
463	                    let arr = self
464	                        .value
465	                        .as_ref()
466	                        .unwrap()
467	                        .as_array()
468	                        .expect("compile validated");
469	                    !arr.contains(v)
470	                }
471	                None => true, // missing → keep
472	            },
473	        })
474	    }
475	}
