477	// ── Explode spec ──
478	
479	/// Spec for [`TransformStage::Explode`]. Fans one record out into N records
480	/// based on the array at `path`. Compiled into a [`CompiledExplode`] at
481	/// pipeline-build time; per-record work is one path resolve + N clones +
482	/// N merges.
483	#[cfg(feature = "transform-explode")]
484	#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, schemars::JsonSchema)]
485	pub struct ExplodeSpec {
486	    /// JSONPath subset (bare key, dot path, bracketed string key).
487	    pub path: String,
488	    /// Prefix prepended to each element field when the element is an object.
489	    /// Defaults (when `None`) to the last segment of `path`. Empty string =
490	    /// no prefix (pure LATERAL FLATTEN).
491	    #[serde(default, skip_serializing_if = "Option::is_none")]
492	    pub prefix: Option<String>,
493	    /// Separator between prefix and each element field. Default `"_"`.
494	    #[serde(default = "default_explode_separator")]
495	    pub separator: String,
496	    /// What to do when `path` doesn't yield a non-empty array.
497	    #[serde(default)]
498	    pub on_missing: OnMissing,
499	}
500	
501	/// Behaviour when an [`ExplodeSpec`]'s `path` doesn't yield a non-empty
502	/// array. The default is `Passthrough` because silently dropping records
503	/// is the worst failure mode for ETL pipelines — surfacing the record
504	/// unchanged lets downstream stages decide.
505	#[cfg(feature = "transform-explode")]
506	#[derive(
507	    Debug,
508	    Clone,
509	    Copy,
510	    PartialEq,
511	    Eq,
512	    Default,
513	    serde::Serialize,
514	    serde::Deserialize,
515	    schemars::JsonSchema,
516	)]
517	#[serde(rename_all = "snake_case")]
518	pub enum OnMissing {
519	    /// Emit the original record unchanged.
520	    #[default]
521	    Passthrough,
522	    /// Emit zero records.
523	    Drop,
524	    /// Return [`FaucetError::Transform`].
525	    Error,
526	}
527	
528	#[cfg(feature = "transform-explode")]
529	fn default_explode_separator() -> String {
530	    "_".to_owned()
531	}
532	
533	/// Pre-compiled explode: path parsed once, prefix resolved once.
534	///
535	/// `pub` (rather than the spec's `pub(crate)`) so it can sit inside the
536	/// `pub` [`CompiledStage::Explode`] variant without tripping the
537	/// `private_interfaces` lint — same shape as the already-`pub`
538	/// [`CompiledFilter`] sibling that backs [`CompiledStage::Filter`].
539	#[cfg(feature = "transform-explode")]
540	#[derive(Debug)]
541	pub struct CompiledExplode {
542	    pub path: CompiledPath,
543	    pub prefix: String,
544	    pub separator: String,
545	    pub on_missing: OnMissing,
546	}
547	
548	#[cfg(feature = "transform-explode")]
549	impl CompiledExplode {
550	    fn compile(spec: &ExplodeSpec) -> Result<Self, FaucetError> {
551	        let path = CompiledPath::compile(&spec.path).map_err(|e| match e {
552	            FaucetError::Transform(msg) => FaucetError::Transform(format!("explode: {msg}")),
553	            other => other,
554	        })?;
555	        let prefix = match &spec.prefix {
556	            Some(p) => p.clone(),
557	            None => path.last_segment().to_owned(),
558	        };
559	        Ok(Self {
560	            path,
561	            prefix,
562	            separator: spec.separator.clone(),
563	            on_missing: spec.on_missing,
564	        })
565	    }
566	
567	    fn apply(&self, rec: Value) -> Result<Vec<Value>, FaucetError> {
568	        // Resolve the value at `path`. If it's a non-empty array, fan out.
569	        // Otherwise, route through `on_missing`.
570	        let target = self.path.resolve(&rec)?;
571	        let Some(Value::Array(elements)) = target.cloned() else {
572	            return self.handle_missing(rec);
573	        };
574	        if elements.is_empty() {
575	            return self.handle_missing(rec);
576	        }
577	        let (parent_segments, leaf) = self.path.parent_and_leaf();
578	        let parent_segments = parent_segments.to_vec();
579	        let leaf = leaf.to_owned();
580	        let mut out: Vec<Value> = Vec::with_capacity(elements.len());
581	        for element in elements {
582	            let mut child = rec.clone();
583	            self.merge_one(&mut child, &parent_segments, &leaf, element)?;
584	            out.push(child);
585	        }
586	        Ok(out)
587	    }
588	
589	    fn handle_missing(&self, rec: Value) -> Result<Vec<Value>, FaucetError> {
590	        match self.on_missing {
591	            OnMissing::Passthrough => Ok(vec![rec]),
592	            OnMissing::Drop => Ok(vec![]),
593	            OnMissing::Error => Err(FaucetError::Transform(format!(
594	                "explode: path '{}' did not yield a non-empty array",
595	                self.path.normalised
596	            ))),
597	        }
598	    }
599	
600	    fn merge_one(
601	        &self,
602	        record: &mut Value,
603	        parent_segments: &[PathSegment],
604	        leaf: &str,
605	        element: Value,
606	    ) -> Result<(), FaucetError> {
607	        let Some(parent_map) = CompiledPath::resolve_segments_mut(record, parent_segments)? else {
608	            return Err(FaucetError::Transform(format!(
609	                "explode: parent container at '{}' unexpectedly missing during merge",
610	                self.path.normalised
611	            )));
612	        };
613	        match element {
614	            Value::Object(elem_map) => {
615	                parent_map.remove(leaf);
616	                for (k, v) in elem_map {
617	                    let new_key = if self.prefix.is_empty() {
618	                        k
619	                    } else {
620	                        format!("{}{}{}", self.prefix, self.separator, k)
621	                    };
622	                    if parent_map.contains_key(&new_key) {
623	                        return Err(FaucetError::Transform(format!(
624	                            "explode produced duplicate key '{new_key}'"
625	                        )));
626	                    }
627	                    parent_map.insert(new_key, v);
628	                }
629	            }
630	            other => {
631	                // Scalar / null / array — replace in place.
632	                parent_map.insert(leaf.to_owned(), other);
633	            }
634	        }
635	        Ok(())
636	    }
637	}
