641	/// Spec for [`TransformStage::CdcUnwrap`]. Normalizes a CDC change-event
642	/// envelope (`{op, before, after, …}`) into a flat row plus a marker field,
643	/// so a downstream upsert sink never needs to understand CDC. A 1→0|1 stage:
644	/// DDL/truncate events (and non-delete events with no `after` image) are
645	/// dropped.
646	#[cfg(feature = "transform-cdc-unwrap")]
647	#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, schemars::JsonSchema)]
648	pub struct CdcUnwrapSpec {
649	    /// Envelope field holding the operation. Default `"op"`.
650	    #[serde(default = "cdc_default_op_field")]
651	    pub op_field: String,
652	    /// Envelope field holding the post-image. Default `"after"`.
653	    #[serde(default = "cdc_default_after_field")]
654	    pub after_field: String,
655	    /// Envelope field holding the pre-image. Default `"before"`.
656	    #[serde(default = "cdc_default_before_field")]
657	    pub before_field: String,
658	    /// Optional fallback for the delete key when `before` is null (Mongo
659	    /// carries the key in `document_key`). Default `"document_key"`.
660	    #[serde(default = "cdc_default_key_field")]
661	    pub key_field: String,
662	    /// Field stamped on every emitted row. Default `"__op"`.
663	    #[serde(default = "cdc_default_marker_field")]
664	    pub marker_field: String,
665	    /// `op` values that mean delete. Default covers all three CDC vocabularies.
666	    #[serde(default = "cdc_default_delete_ops")]
667	    pub delete_ops: Vec<String>,
668	    /// `op` values dropped entirely (1→0). Default `["ddl", "truncate"]`.
669	    #[serde(default = "cdc_default_drop_ops")]
670	    pub drop_ops: Vec<String>,
671	}
672	
673	#[cfg(feature = "transform-cdc-unwrap")]
674	fn cdc_default_op_field() -> String {
675	    "op".into()
676	}
677	#[cfg(feature = "transform-cdc-unwrap")]
678	fn cdc_default_after_field() -> String {
679	    "after".into()
680	}
681	#[cfg(feature = "transform-cdc-unwrap")]
682	fn cdc_default_before_field() -> String {
683	    "before".into()
684	}
685	#[cfg(feature = "transform-cdc-unwrap")]
686	fn cdc_default_key_field() -> String {
687	    "document_key".into()
688	}
689	#[cfg(feature = "transform-cdc-unwrap")]
690	fn cdc_default_marker_field() -> String {
691	    "__op".into()
692	}
693	#[cfg(feature = "transform-cdc-unwrap")]
694	fn cdc_default_delete_ops() -> Vec<String> {
695	    vec!["d".into(), "delete".into()]
696	}
697	#[cfg(feature = "transform-cdc-unwrap")]
698	fn cdc_default_drop_ops() -> Vec<String> {
699	    vec!["ddl".into(), "truncate".into()]
700	}
701	
702	#[cfg(feature = "transform-cdc-unwrap")]
703	impl Default for CdcUnwrapSpec {
704	    fn default() -> Self {
705	        Self {
706	            op_field: cdc_default_op_field(),
707	            after_field: cdc_default_after_field(),
708	            before_field: cdc_default_before_field(),
709	            key_field: cdc_default_key_field(),
710	            marker_field: cdc_default_marker_field(),
711	            delete_ops: cdc_default_delete_ops(),
712	            drop_ops: cdc_default_drop_ops(),
713	        }
714	    }
715	}
