717	/// Pre-compiled cdc_unwrap. `pub` so it can sit inside the `pub`
718	/// [`CompiledStage::CdcUnwrap`] variant without triggering the
719	/// `private_interfaces` lint — same shape as the already-`pub`
720	/// [`CompiledExplode`] sibling that backs [`CompiledStage::Explode`].
721	#[cfg(feature = "transform-cdc-unwrap")]
722	#[derive(Debug, Clone)]
723	pub struct CompiledCdcUnwrap {
724	    spec: CdcUnwrapSpec,
725	}
726	
727	#[cfg(feature = "transform-cdc-unwrap")]
728	impl CompiledCdcUnwrap {
729	    fn compile(spec: &CdcUnwrapSpec) -> Result<Self, FaucetError> {
730	        Ok(Self { spec: spec.clone() })
731	    }
732	
733	    fn apply(&self, rec: Value) -> Result<Vec<Value>, FaucetError> {
734	        let s = &self.spec;
735	        let op = rec.get(&s.op_field).and_then(Value::as_str).unwrap_or("");
736	        if s.drop_ops.iter().any(|d| d == op) {
737	            return Ok(vec![]);
738	        }
739	        let is_delete = s.delete_ops.iter().any(|d| d == op);
740	        let row = if is_delete {
741	            match rec.get(&s.before_field) {
742	                Some(Value::Object(m)) => Some(Value::Object(m.clone())),
743	                _ => match rec.get(&s.key_field) {
744	                    Some(Value::Object(m)) => Some(Value::Object(m.clone())),
745	                    _ => None,
746	                },
747	            }
748	        } else {
749	            match rec.get(&s.after_field) {
750	                Some(Value::Object(m)) => Some(Value::Object(m.clone())),
751	                _ => None,
752	            }
753	        };
754	        let Some(Value::Object(mut map)) = row else {
755	            if is_delete {
756	                tracing::warn!(
757	                    op,
758	                    key_field = %s.key_field,
759	                    before_field = %s.before_field,
760	                    "cdc_unwrap: dropping delete event with no usable key (no `before` image and no key_field object)"
761	                );
762	            } else {
763	                tracing::warn!(
764	                    op,
765	                    after_field = %s.after_field,
766	                    "cdc_unwrap: dropping non-delete event with no row image"
767	                );
768	            }
769	            return Ok(vec![]);
770	        };
771	        let marker = if is_delete { "d" } else { "u" };
772	        map.insert(s.marker_field.clone(), Value::String(marker.to_string()));
773	        Ok(vec![Value::Object(map)])
774	    }
775	}
