777	/// Compile a [`TransformStage`] into its [`CompiledStage`] form.
778	pub fn compile_stage(s: &TransformStage) -> Result<CompiledStage, FaucetError> {
779	    match s {
780	        TransformStage::Map(t) => Ok(CompiledStage::Map(compile_record(t)?)),
781	        #[cfg(feature = "transform-filter")]
782	        TransformStage::Filter(spec) => Ok(CompiledStage::Filter(CompiledFilter::compile(spec)?)),
783	        #[cfg(feature = "transform-explode")]
784	        TransformStage::Explode(spec) => {
785	            Ok(CompiledStage::Explode(CompiledExplode::compile(spec)?))
786	        }
787	        #[cfg(feature = "transform-cdc-unwrap")]
788	        TransformStage::CdcUnwrap(spec) => {
789	            Ok(CompiledStage::CdcUnwrap(CompiledCdcUnwrap::compile(spec)?))
790	        }
791	        TransformStage::Custom(f) => Ok(CompiledStage::Custom(Arc::clone(f))),
792	        TransformStage::PageFn(f) => Ok(CompiledStage::PageFn(Arc::clone(f))),
793	    }
794	}
795	
796	/// Per-record stage runner. Returns 0..N output records. Pure; no metrics.
797	pub fn apply_stages(rec: Value, stages: &[CompiledStage]) -> Result<Vec<Value>, FaucetError> {
798	    let mut acc = vec![rec];
799	    for stage in stages {
800	        let mut next: Vec<Value> = Vec::with_capacity(acc.len());
801	        for r in acc {
802	            next.extend(apply_one_stage(r, stage)?);
803	        }
804	        acc = next;
805	    }
806	    Ok(acc)
807	}
808	
809	/// Page-granular stage runner. Per-record stages (`Map`/`Filter`/`Explode`/
810	/// `Custom`) flat-map over the current page; `PageFn` stages transform the whole
811	/// page at once. Preserves declared order, so `filter → sql → select` works.
812	pub fn apply_stages_to_page(
813	    mut records: Vec<Value>,
814	    stages: &[CompiledStage],
815	) -> Result<Vec<Value>, FaucetError> {
816	    for stage in stages {
817	        match stage {
818	            CompiledStage::PageFn(f) => {
819	                records = f(records)?;
820	            }
821	            per_record => {
822	                let mut next = Vec::with_capacity(records.len());
823	                for r in records {
824	                    next.extend(apply_one_stage(r, per_record)?);
825	                }
826	                records = next;
827	            }
828	        }
829	    }
830	    Ok(records)
831	}
832	
833	fn apply_one_stage(rec: Value, stage: &CompiledStage) -> Result<Vec<Value>, FaucetError> {
834	    match stage {
835	        CompiledStage::Map(t) => Ok(vec![crate::transform::apply_all(
836	            rec,
837	            std::slice::from_ref(t),
838	        )?]),
839	        #[cfg(feature = "transform-filter")]
840	        CompiledStage::Filter(f) => {
841	            if f.evaluate(&rec)? {
842	                Ok(vec![rec])
843	            } else {
844	                Ok(vec![])
845	            }
846	        }
847	        #[cfg(feature = "transform-explode")]
848	        CompiledStage::Explode(e) => e.apply(rec),
849	        #[cfg(feature = "transform-cdc-unwrap")]
850	        CompiledStage::CdcUnwrap(c) => c.apply(rec),
851	        CompiledStage::Custom(f) => Ok(f(rec)),
852	        CompiledStage::PageFn(_) => Err(FaucetError::Transform(
853	            "PageFn is a page-level stage and cannot run in a per-record context; \
854	             use apply_stages_to_page"
855	                .to_owned(),
856	        )),
857	    }
858	}
