480	/// One-line summary of every transform compiled into this build. Used by
481	/// `faucet list`.
482	pub fn transform_descriptions() -> Vec<(&'static str, &'static str)> {
483	    registry()
484	        .into_iter()
485	        .map(|t| (t.kind, t.description))
486	        .collect()
487	}
