494	// Keep in sync with faucet_core::{RecordCheck, BatchCheck} — one entry per check variant.
495	/// One-line descriptions of the available quality checks, for `faucet list`.
496	/// The `json_schema` entry only appears when the `quality-jsonschema` feature
497	/// is enabled, mirroring `faucet schema quality` so `list` and `schema` agree.
498	#[cfg(feature = "quality")]
499	pub fn quality_descriptions() -> Vec<(&'static str, &'static str)> {
500	    let mut checks = vec![
501	        ("not_null", "field present and non-null"),
502	        ("not_empty", "string non-empty after trim"),
503	        ("regex_match", "string matches a regex"),
504	        ("value_in_set", "value is in an allowed set"),
505	        ("not_in_set", "value is not in a forbidden set"),
506	        ("compare", "numeric/scalar comparison (gt/gte/lt/lte/eq/ne)"),
507	        ("type_is", "value is of an expected JSON type"),
508	        ("string_length", "string length within [min,max]"),
509	    ];
510	    #[cfg(feature = "quality-jsonschema")]
511	    checks.push((
512	        "json_schema",
513	        "record validates against a JSON Schema (feature-gated)",
514	    ));
515	    checks.extend([
516	        ("row_count", "batch row count within [min,max]"),
517	        ("null_rate", "batch null rate of a field <= max"),
518	        ("unique", "composite key unique within the batch"),
519	        (
520	            "distinct_count",
521	            "distinct values of a field within [min,max]",
522	        ),
523	    ]);
524	    checks
525	}
