527	/// Return the JSON Schema for the named transform's config. Mirrors
528	/// `registry::source_schema` / `sink_schema` so `faucet schema transform <name>`
529	/// reads symmetrically with the connector variants.
530	pub fn transform_schema(name: &str) -> CliResult<Value> {
531	    registry()
532	        .into_iter()
533	        .find(|t| t.kind == name)
534	        .map(|t| (t.schema_fn)())
535	        .ok_or_else(|| unknown_transform(name))
536	}
537	
538	fn unknown_transform(name: &str) -> CliError {
539	    let available = available_transforms();
540	    CliError::UnknownTransform {
541	        name: name.to_owned(),
542	        available: if available.is_empty() {
543	            "(none — rebuild faucet-cli with the `transforms` feature enabled)".to_owned()
544	        } else {
545	            available.join(", ")
546	        },
547	    }
548	}
549	
550	#[cfg(any(feature = "transforms", feature = "transform-cdc-unwrap"))]
551	fn schema<T: JsonSchema>() -> Value {
552	    serde_json::to_value(schema_for!(T)).unwrap_or_else(|_| serde_json::json!({"type": "object"}))
553	}
554	
555	#[cfg(any(feature = "transforms", feature = "transform-cdc-unwrap"))]
556	fn decode<T: serde::de::DeserializeOwned>(name: &str, config: Value) -> CliResult<T> {
557	    serde_json::from_value(config).map_err(|e| CliError::InvalidTransform {
558	        name: name.to_owned(),
559	        message: e.to_string(),
560	    })
561	}
562	
563	#[cfg(feature = "transform-sql")]
564	fn schema_sql() -> Value {
565	    serde_json::to_value(faucet_core::schema_for!(
566	        faucet_transform_sql::SqlTransformConfig
567	    ))
568	    .unwrap_or(Value::Null)
569	}
