571	#[cfg(feature = "transform-sql")]
572	fn decode_sql(kind: &str, config: Value) -> CliResult<faucet_transform_sql::SqlTransformConfig> {
573	    serde_json::from_value(config).map_err(|e| CliError::InvalidTransform {
574	        name: kind.to_owned(),
575	        message: e.to_string(),
576	    })
577	}
