#![cfg_attr(docsrs, feature(doc_cfg))]
//! WebAssembly-as-transform for faucet-stream.
//!
//! Loads a user-provided, precompiled `.wasm` module through [`wasmtime`] and
//! invokes an exported function once per record. Any language that compiles to
//! core WebAssembly (Rust, TinyGo, AssemblyScript, Zig, C/C++, …) can express
//! arbitrary per-record logic in a faucet pipeline without forking the project.
//!
//! [`WasmTransformConfig`] is the user-facing config; [`WasmTransform`] is the
//! compiled runtime that owns the wasmtime engine + module and runs it per
//! page via [`WasmTransform::into_page_stage`].
//!
//! # Sandbox
//!
//! Modules run in a strict sandbox. Each record call is bounded by
//! [`fuel`](WasmTransformConfig::fuel_limit) (a deterministic CPU limit) and by
//! [`memory`](WasmTransformConfig::memory_limit_mb) (linear-memory cap). The
//! only host imports are `faucet_v1::log` and `faucet_v1::now_ns` — there is no
//! filesystem, network, clock, or environment access in v1.
//!
//! # ABI (v1)
//!
//! The module must export:
//! - `alloc(len: i32) -> i32` — allocate `len` bytes of linear memory, return
//!   the offset. The host writes the input JSON there before each call.
//! - `<function>(ptr: i32, len: i32) -> i64` — the transform entry point
//!   (name from [`WasmTransformConfig::function`], default `"transform"`).
//!   Input is UTF-8 JSON at `[ptr, ptr+len)`. The packed return value is
//!   `(out_ptr as u64) << 32 | (out_len as u64)`:
//!   - `0` → drop the record (filter it out).
//!   - [`u64::MAX`] → error; the host reads the message from the optional
//!     `error_ptr()` / `error_len()` exports.
//!   - otherwise → the output UTF-8 JSON at `[out_ptr, out_ptr+out_len)`.
//! - `memory` — the exported linear memory (standard name).
//!
//! Optional exports: `free(ptr: i32, len: i32)` (host calls it after copying
//! output out), `error_ptr() -> i32` / `error_len() -> i32` (error message).
//!
//! See the crate README and the `docs/book` cookbook page for full details and
//! reference modules.

mod abi;
mod config;
mod engine;
mod instance;
pub(crate) mod metrics;
mod runtime;

pub use config::{WasmOnError, WasmTransformConfig};
pub use runtime::WasmTransform;

//! Config types for the WASM transform. No I/O or wasmtime here.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Configuration for the `wasm` transform.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct WasmTransformConfig {
    /// Filesystem path to the precompiled `.wasm` module (absolute, or relative
    /// to the working directory). URLs are not supported in v1.
    pub module: String,
    /// Name of the exported transform function. Default `"transform"`.
    #[serde(default = "default_function")]
    pub function: String,
    /// Linear-memory cap for the module, in mebibytes. A record that grows
    /// memory past this limit fails that record (routed by `on_error`).
    /// Default `16`. The practical lower bound for ~1 KB JSON records is ~8 MB.
    #[serde(default = "default_memory_limit_mb")]
    pub memory_limit_mb: u32,
    /// wasmtime fuel budget per record — a deterministic CPU bound. A record
    /// that exhausts its fuel fails (routed by `on_error`). Default
    /// `10_000_000`. Fuel is the effective CPU limit in v1 (there are no
    /// blocking host calls, so a wall-clock timeout would be redundant).
    #[serde(default = "default_fuel_limit")]
    pub fuel_limit: u64,
    /// What to do when a record fails inside the module (trap, fuel/memory
    /// exhaustion, ABI violation, or non-JSON output). Default `fail`.
    #[serde(default)]
    pub on_error: WasmOnError,
    /// Re-stat the module file's mtime before each page; recompile and swap in
    /// the new module atomically at the page boundary if it changed. In-flight
    /// records within a page always use one module. Default `false`.
    #[serde(default)]
    pub reload_on_change: bool,
}

/// Policy for a per-record module failure.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum WasmOnError {
    /// Abort the whole run with a [`faucet_core::FaucetError::Transform`]
    /// (the default; matches every other transform's fail-fast behaviour).
    #[default]
    Fail,
    /// Drop the failing record and continue (a warning + metric is emitted).
    Skip,
    /// Emit the record unchanged and continue (a warning + metric is emitted).
    Passthrough,
}

fn default_function() -> String {
    "transform".to_owned()
}

fn default_memory_limit_mb() -> u32 {
    16
}

fn default_fuel_limit() -> u64 {
    10_000_000
}

impl WasmTransformConfig {
    /// The low-cardinality metric label for this module — the file basename.
    pub(crate) fn module_label(&self) -> String {
        std::path::Path::new(&self.module)
            .file_name()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_else(|| self.module.clone())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn decodes_minimal_config_with_defaults() {
        let cfg: WasmTransformConfig =
            serde_json::from_value(json!({"module": "./t.wasm"})).unwrap();
        assert_eq!(cfg.module, "./t.wasm");
        assert_eq!(cfg.function, "transform");
        assert_eq!(cfg.memory_limit_mb, 16);
        assert_eq!(cfg.fuel_limit, 10_000_000);
        assert_eq!(cfg.on_error, WasmOnError::Fail);
        assert!(!cfg.reload_on_change);
    }

    #[test]
    fn decodes_full_config() {
        let cfg: WasmTransformConfig = serde_json::from_value(json!({
            "module": "/abs/redact.wasm",
            "function": "run",
            "memory_limit_mb": 32,
            "fuel_limit": 5000,
            "on_error": "skip",
            "reload_on_change": true
        }))
        .unwrap();
        assert_eq!(cfg.function, "run");
        assert_eq!(cfg.memory_limit_mb, 32);
        assert_eq!(cfg.fuel_limit, 5000);
        assert_eq!(cfg.on_error, WasmOnError::Skip);
        assert!(cfg.reload_on_change);
    }

    #[test]
    fn rejects_missing_module() {
        let err = serde_json::from_value::<WasmTransformConfig>(json!({})).unwrap_err();
        assert!(err.to_string().contains("module"), "{err}");
    }

    #[test]
    fn rejects_unknown_on_error() {
        let err =
            serde_json::from_value::<WasmTransformConfig>(json!({"module": "t.wasm", "on_error": "explode"}))
                .unwrap_err();
        assert!(err.to_string().to_lowercase().contains("on_error") || err.to_string().contains("explode"), "{err}");
    }

    #[test]
    fn module_label_is_basename() {
        let cfg: WasmTransformConfig =
            serde_json::from_value(json!({"module": "/a/b/redact_email.wasm"})).unwrap();
        assert_eq!(cfg.module_label(), "redact_email.wasm");
        let bare: WasmTransformConfig =
            serde_json::from_value(json!({"module": "x.wasm"})).unwrap();
        assert_eq!(bare.module_label(), "x.wasm");
    }

    #[test]
    fn schema_builds_with_module_property() {
        let schema = schemars::schema_for!(WasmTransformConfig);
        let json = serde_json::to_value(&schema).unwrap();
        assert!(
            json.get("properties")
                .and_then(|p| p.get("module"))
                .is_some()
        );
    }
}

//! Pure encode/decode of the v1 WASM transform ABI. No wasmtime here — this
//! module is just the bit-twiddling and outcome classification, so it is
//! trivially unit-testable.

/// Packed return value meaning "drop this record" (filter it out).
pub(crate) const DROP: u64 = 0;

/// Packed return value meaning "the module signalled an error"; the host reads
/// the message from the optional `error_ptr()` / `error_len()` exports.
pub(crate) const ERROR: u64 = u64::MAX;

/// A packed transform return value, classified before touching memory.
#[derive(Debug, PartialEq, Eq)]
pub(crate) enum RawOutcome {
    /// Drop the record.
    Drop,
    /// The module signalled an error.
    Error,
    /// Emit output JSON located at `[ptr, ptr + len)` in linear memory.
    Emit { ptr: u32, len: u32 },
}

/// Split a packed `u64` into `(ptr, len)` — high 32 bits are the pointer, low
/// 32 bits the length.
pub(crate) fn unpack(ret: u64) -> (u32, u32) {
    ((ret >> 32) as u32, (ret & 0xFFFF_FFFF) as u32)
}

/// Classify a raw packed return value from the `transform` export.
pub(crate) fn classify(ret: u64) -> RawOutcome {
    match ret {
        DROP => RawOutcome::Drop,
        ERROR => RawOutcome::Error,
        other => {
            let (ptr, len) = unpack(other);
            RawOutcome::Emit { ptr, len }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unpack_splits_hi_lo() {
        assert_eq!(unpack(0), (0, 0));
        assert_eq!(unpack((7u64 << 32) | 5), (7, 5));
        assert_eq!(unpack(0xFFFF_FFFE_0000_0003), (0xFFFF_FFFE, 3));
    }

    #[test]
    fn classify_zero_is_drop() {
        assert_eq!(classify(DROP), RawOutcome::Drop);
    }

    #[test]
    fn classify_max_is_error() {
        assert_eq!(classify(ERROR), RawOutcome::Error);
    }

    #[test]
    fn classify_other_is_emit() {
        assert_eq!(
            classify((1024u64 << 32) | 42),
            RawOutcome::Emit {
                ptr: 1024,
                len: 42
            }
        );
    }

    #[test]
    fn classify_zero_len_nonzero_ptr_is_emit_empty() {
        // ptr set, len 0 → a legitimate empty-output emit (not the DROP
        // sentinel, which requires the whole word to be zero).
        assert_eq!(
            classify(64u64 << 32),
            RawOutcome::Emit { ptr: 64, len: 0 }
        );
    }
}

//! WASM-transform metrics. Emitted directly via the `metrics` facade; the
//! recorder is installed by the pipeline's observability layer. The `module`
//! label is the module file basename — low cardinality, user-controlled.

use metrics::{counter, gauge, histogram};

/// One transform invocation with its terminal outcome (`ok` / `filter` /
/// `error`). `filter` is the module returning the drop sentinel.
pub(crate) fn invocation(module: &str, outcome: &'static str) {
    counter!(
        "faucet_wasm_invocations_total",
        "module" => module.to_string(),
        "outcome" => outcome,
    )
    .increment(1);
}

/// Wall-clock duration of one `transform` call (seconds).
pub(crate) fn invocation_duration(module: &str, secs: f64) {
    histogram!(
        "faucet_wasm_invocation_duration_seconds",
        "module" => module.to_string(),
    )
    .record(secs);
}

/// Fuel consumed by one `transform` call.
pub(crate) fn fuel_consumed(module: &str, fuel: u64) {
    counter!(
        "faucet_wasm_fuel_consumed_total",
        "module" => module.to_string(),
    )
    .increment(fuel);
}

/// Peak linear-memory size observed for the page's instance (bytes).
pub(crate) fn memory_bytes(module: &str, bytes: u64) {
    gauge!(
        "faucet_wasm_memory_bytes",
        "module" => module.to_string(),
    )
    .set(bytes as f64);
}

/// Cost of compiling the module (seconds) — hot-reload visibility.
pub(crate) fn compile_duration(module: &str, secs: f64) {
    histogram!(
        "faucet_wasm_compile_duration_seconds",
        "module" => module.to_string(),
    )
    .record(secs);
}

//! The wasmtime engine + compiled module, and per-page instance creation.
//!
//! The [`Engine`] and [`Module`] are compiled once (expensive) and reused
//! across the row's pages. Each page gets a fresh [`Store`] + `Instance`
//! (cheap), which bounds linear-memory growth to a single page and keeps the
//! module stateless across pages.

use crate::config::WasmTransformConfig;
use crate::instance::WasmInstance;
use crate::metrics;
use faucet_core::FaucetError;
use std::path::PathBuf;
use std::time::{Instant, SystemTime};
use wasmtime::{Caller, Config, Engine, Extern, Linker, Memory, Module, Store, StoreLimits, StoreLimitsBuilder};

/// Per-store host state: the memory limiter and a monotonic epoch for the
/// `now_ns` host import.
pub(crate) struct HostState {
    pub(crate) limits: StoreLimits,
    pub(crate) epoch_base: Instant,
}

/// A compiled WASM transform: owns the wasmtime engine, the compiled module,
/// and the import linker. Cheap to build an instance from, per page.
pub(crate) struct WasmEngine {
    engine: Engine,
    module: Module,
    linker: Linker<HostState>,
    pub(crate) function: String,
    pub(crate) memory_bytes: usize,
    pub(crate) fuel_limit: u64,
    pub(crate) module_label: String,
    path: PathBuf,
    mtime: Option<SystemTime>,
    reload_on_change: bool,
}

impl WasmEngine {
    /// Compile the module and validate the ABI exports. Fails fast (in `new()`)
    /// on a missing file, a malformed module, or a missing/mis-typed export.
    pub(crate) fn compile(cfg: &WasmTransformConfig) -> Result<Self, FaucetError> {
        let path = PathBuf::from(&cfg.module);
        let module_label = cfg.module_label();
        let bytes = std::fs::read(&path).map_err(|e| {
            FaucetError::Config(format!(
                "wasm transform: cannot read module '{}': {e}",
                path.display()
            ))
        })?;
        let mtime = std::fs::metadata(&path).and_then(|m| m.modified()).ok();

        let mut config = Config::new();
        config.consume_fuel(true);
        let engine = Engine::new(&config).map_err(|e| {
            FaucetError::Config(format!("wasm transform: engine init failed: {e}"))
        })?;

        let compile_start = Instant::now();
        let module = Module::new(&engine, &bytes).map_err(|e| {
            FaucetError::Config(format!(
                "wasm transform: failed to compile '{}': {e}",
                path.display()
            ))
        })?;
        metrics::compile_duration(&module_label, compile_start.elapsed().as_secs_f64());

        let linker = build_linker(&engine)?;

        let memory_bytes = (cfg.memory_limit_mb as usize) * 1024 * 1024;
        let engine_wrap = Self {
            engine,
            module,
            linker,
            function: cfg.function.clone(),
            memory_bytes,
            fuel_limit: cfg.fuel_limit,
            module_label,
            path,
            mtime,
            reload_on_change: cfg.reload_on_change,
        };

        // Validate the ABI by instantiating once and resolving the required
        // exports. A bad module surfaces here, at config-load time.
        let mut probe = engine_wrap.new_page_instance()?;
        probe.check_abi(&engine_wrap.function)?;
        Ok(engine_wrap)
    }

    /// Re-stat the module file; if its mtime changed, recompile and atomically
    /// swap the module in. A failed recompile keeps the last-known-good module
    /// and logs a warning (so a bad hot edit never takes down a running
    /// pipeline). No-op unless `reload_on_change`.
    pub(crate) fn reload_if_changed(&mut self) {
        if !self.reload_on_change {
            return;
        }
        let cur = std::fs::metadata(&self.path)
            .and_then(|m| m.modified())
            .ok();
        if cur == self.mtime {
            return;
        }
        // mtime moved (or became unreadable) — attempt a recompile.
        match std::fs::read(&self.path) {
            Ok(bytes) => {
                let start = Instant::now();
                match Module::new(&self.engine, &bytes) {
                    Ok(module) => {
                        metrics::compile_duration(
                            &self.module_label,
                            start.elapsed().as_secs_f64(),
                        );
                        self.module = module;
                        self.mtime = cur;
                        tracing::info!(
                            target: "faucet::transform::wasm",
                            module = %self.module_label,
                            "reloaded changed wasm module"
                        );
                    }
                    Err(e) => {
                        // Keep last-known-good; don't advance mtime so we retry
                        // once the file is fixed.
                        tracing::warn!(
                            target: "faucet::transform::wasm",
                            module = %self.module_label,
                            error = %e,
                            "wasm module changed but failed to recompile; keeping previous module"
                        );
                    }
                }
            }
            Err(e) => {
                tracing::warn!(
                    target: "faucet::transform::wasm",
                    module = %self.module_label,
                    error = %e,
                    "wasm module changed but became unreadable; keeping previous module"
                );
            }
        }
    }

    /// Create a fresh store + instance for one page.
    pub(crate) fn new_page_instance(&self) -> Result<WasmInstance, FaucetError> {
        let limits = StoreLimitsBuilder::new()
            .memory_size(self.memory_bytes)
            .trap_on_grow_failure(true)
            .build();
        let mut store = Store::new(
            &self.engine,
            HostState {
                limits,
                epoch_base: Instant::now(),
            },
        );
        store.limiter(|state| &mut state.limits);
        let instance = self
            .linker
            .instantiate(&mut store, &self.module)
            .map_err(|e| {
                FaucetError::Transform(format!(
                    "wasm transform: instantiation failed for '{}': {e}",
                    self.module_label
                ))
            })?;
        WasmInstance::new(store, instance, &self.function, self.fuel_limit, self.module_label.clone())
    }
}

/// Build the import linker with the `faucet_v1` host functions.
fn build_linker(engine: &Engine) -> Result<Linker<HostState>, FaucetError> {
    let mut linker = Linker::new(engine);
    linker
        .func_wrap(
            "faucet_v1",
            "log",
            |mut caller: Caller<'_, HostState>, level: i32, ptr: i32, len: i32| {
                let msg = read_host_string(&mut caller, ptr, len);
                emit_log(level, &msg);
            },
        )
        .map_err(|e| FaucetError::Config(format!("wasm transform: linker log: {e}")))?;
    linker
        .func_wrap(
            "faucet_v1",
            "now_ns",
            |caller: Caller<'_, HostState>| -> i64 {
                caller.data().epoch_base.elapsed().as_nanos() as i64
            },
        )
        .map_err(|e| FaucetError::Config(format!("wasm transform: linker now_ns: {e}")))?;
    Ok(linker)
}

fn emit_log(level: i32, msg: &str) {
    match level {
        0 => tracing::trace!(target: "faucet::transform::wasm::module", "{msg}"),
        1 => tracing::debug!(target: "faucet::transform::wasm::module", "{msg}"),
        2 => tracing::info!(target: "faucet::transform::wasm::module", "{msg}"),
        3 => tracing::warn!(target: "faucet::transform::wasm::module", "{msg}"),
        _ => tracing::error!(target: "faucet::transform::wasm::module", "{msg}"),
    }
}

/// Best-effort read of a UTF-8 string from module memory for a host call.
/// Never traps the caller — a bad pointer just yields an empty string.
fn read_host_string(caller: &mut Caller<'_, HostState>, ptr: i32, len: i32) -> String {
    let Some(Extern::Memory(mem)) = caller.get_export("memory") else {
        return String::new();
    };
    let (ptr, len) = (ptr as usize, len as usize);
    let data = mem.data(&caller);
    match data.get(ptr..ptr.saturating_add(len)) {
        Some(slice) => String::from_utf8_lossy(slice).into_owned(),
        None => String::new(),
    }
}

/// Look up the exported linear memory named `memory`.
pub(crate) fn memory_export(
    store: &mut Store<HostState>,
    instance: &wasmtime::Instance,
) -> Result<Memory, FaucetError> {
    instance.get_memory(store, "memory").ok_or_else(|| {
        FaucetError::Config(
            "wasm transform: module does not export a linear memory named 'memory'".to_owned(),
        )
    })
}

